d.push({
    title: "保存",
    url: $("#noLoading#").lazyRule((obj) => {
        let p = "hiker://files/rules/browser_proxy_rules.json";
        let a = fetch(p);
        if (!a || a == "") {
            a = "[]";
        }
        let arr = JSON.parse(a);
        let name = getVar("bp_name", obj.name || "");
        if (name == "") {
            return "toast://name不能为空"
        }
        let mat = getVar("bp_match", obj.match || "");
        let rep = getVar("bp_replace", obj.replace || "");
        let force = getVar("bp_force", "" + (obj.force == true)) == "true";
        let req = JSON.parse(getVar("bp_requestHeaders", JSON.stringify(obj.requestHeaders || {})));
        let resp = JSON.parse(getVar("bp_responseHeaders", JSON.stringify(obj.responseHeaders || [])));
        let obj1 = {
            name: name,
            match: mat,
            replace: rep,
            force: force,
            requestHeaders: req,
            responseHeaders: resp
        };
        arr = arr.filter(it => obj.name == "" || obj.name == null || it.name != obj.name);
        arr.unshift(obj1);
        writeFile(p, JSON.stringify(arr));
        back(true);
        return "toast://保存成功";
    }, obj),
    col_type: "text_3",
});

